export const INITIAL_CTA = {
  /** Containers narrower than this anchor the invitation low, by the thumb and keyboard. */
  compactWidth: 420,
  /** The pattern library's device previews use 720 (--ax-composer-max), so open iPhone Duo gets the one-row composer. */
  composerMaxWidth: 720,
  margin: 16,
  /** Space between the supporting line and the composer. */
  leadGap: 14,
  leadMaxWidthCentered: 400,
  leadMaxWidthPane: 300,
  /** Space between the conversation and the docked composer. */
  conversationGap: 8,
  minGutter: 24,
  /** Hand-over: 500ms on the emphasized curve, no overshoot. Instant under reduced motion. */
  handOverMs: 500,
  handOverCurve: [0.2, 0, 0, 1] as const,
};

