export const MCP_SAID = {
  status: (status: McpStatus, name: string, count: number): string | null => {
    switch (status) {
      case 'reaching':
        return `Reaching ${name}.`;
      case 'validating':
        return 'Validating the connection.';
      case 'discovering':
        return 'Discovering tools.';
      case 'ready':
        return `${name} is ready. ${count === 1 ? '1 tool' : `${count} tools`} discovered.`;
      case 'unreachable':
        return `${name} couldn’t be reached.`;
      case 'expired':
        return `${name}: authentication expired. Reconnect to use its tools.`;
      case 'disconnected':
        return `${name} disconnected. Its configuration is kept.`;
      default:
        return null;
    }
  },
  ask: (label: string) => `${label} needs your approval.`,
  decided: (d: McpDecision, label: string, server: string) =>
    d === 'once' ? `Allowed once: ${label}.` : d === 'always' ? `${label} will run without asking on ${server}.` : `Denied. Nothing was sent to ${server}.`,
  done: (label: string) => `${label} completed.`,
  failed: (label: string) => `${label} failed. The server is still connected.`,
};

