import SwiftUI
import Nucleux

struct AgentColorScreen: View {
    @State private var drafting = true

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 20) {
                Text("Ticket 5512").font(.system(size: 17, weight: .semibold)).foregroundStyle(NucleuxColor.foreground)
                VStack(alignment: .leading, spacing: 0) {
                    row("Draft a reply", ai: true)
                    row("Summarise this thread", ai: true)
                    Divider().overlay(NucleuxColor.border).padding(.vertical, 4)
                    row("Add a note", ai: false)
                    row("Assign to someone", ai: false)
                }
                .padding(.vertical, 6)
                .overlay(RoundedRectangle(cornerRadius: 12).strokeBorder(NucleuxColor.border))
                HStack(spacing: 16) {
                    ForEach(NucleuxIdentity.GlyphContainer.allCases, id: \.self) { k in
                        VStack(spacing: 6) {
                            NucleuxAgentGlyph(k, size: 44, glyph: 22)
                            Text(k.rawValue.capitalized).font(.system(size: 11, weight: .medium)).foregroundStyle(NucleuxColor.mutedForeground)
                        }
                    }
                }
                VStack(spacing: 10) {
                    NucleuxMessageBubble("Where did Q2 renewals land?")
                    NucleuxMessageBubble("£4.1m, 6% ahead of plan — almost all of it enterprise renewals.", agent: "Aria")
                }
                NucleuxAgentPresence(agent: "Aria", activity: "drafting in this document",
                                     detail: "Nothing is saved until you accept it.", active: drafting) {
                    Text("Q2 renewal summary").font(.system(size: 15, weight: .semibold)).foregroundStyle(NucleuxColor.foreground)
                    Text("Renewals closed at 94%, up four points.").font(.system(size: 15)).foregroundStyle(NucleuxColor.foreground)
                }
                NucleuxButton(drafting ? "Stop Aria" : "Let Aria draft", variant: .secondary, size: .sm) { drafting.toggle() }
            }
            .padding(16)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
    }

    private func row(_ label: String, ai: Bool) -> some View {
        HStack(spacing: 12) {
            if ai {
                NucleuxAgentGlyph(.quiet, size: 28, glyph: 16)
            } else {
                NucleuxIconView(.fileText, size: 18).foregroundStyle(NucleuxColor.mutedForeground).frame(width: 28, height: 28)
                    .accessibilityHidden(true)
            }
            Text(label).font(.system(size: 15)).foregroundStyle(NucleuxColor.foreground)
            Spacer()
