struct AttachmentsScreen: View {
    private static let showcase: [NucleuxAttachment] = [
        NucleuxAttachment(id: "p", name: "Northwind-proposal.pdf", kind: .document, state: .uploading, type: "PDF · 34 pages", size: "2.4 MB", progress: 44),
        NucleuxAttachment(id: "r", name: "Research-notes.docx", kind: .document, state: .processing, type: "Word", size: "320 KB"),
        NucleuxAttachment(id: "i", name: "pricing-table.png", kind: .image, state: .ready, type: "PNG", size: "1.2 MB",
                          thumbnail: AttachmentsScreen.sampleThumbnail),
        NucleuxAttachment(id: "b", name: "All-hands-recording.mp4", kind: .document, state: .tooLarge, size: "840 MB",
                          note: NucleuxAttachment.tooLargeNote(limit: "500 MB")),
        NucleuxAttachment(id: "s", name: "Q3-pricing.xlsx", kind: .spreadsheet, state: .failed, type: "Excel", size: "180 KB"),
    ]

    /// A stand-in photo: a soft gradient, like the pattern library's sample image.
    static let sampleThumbnail: Image = {
        let size = CGSize(width: 48, height: 48)
        let image = UIGraphicsImageRenderer(size: size).image { ctx in
            let colors = [UIColor(red: 0.84, green: 0.82, blue: 0.90, alpha: 1).cgColor, UIColor(red: 0.93, green: 0.91, blue: 0.96, alpha: 1).cgColor]
            let gradient = CGGradient(colorsSpace: nil, colors: colors as CFArray, locations: [0, 1])!
            ctx.cgContext.drawLinearGradient(gradient, start: .zero, end: CGPoint(x: size.width, y: size.height), options: [])
        }
        return Image(uiImage: image)
    }()

    @State private var text = ""
    @State private var files: [NucleuxAttachment] = {
        switch ProcessInfo.processInfo.environment["SHOWCASE"] {
        case "1": return AttachmentsScreen.showcase
        case "2": return Array(AttachmentsScreen.showcase.suffix(3))
        default: return []
        }
    }()

    var body: some View {
        VStack {
            Spacer()
            NucleuxPromptComposer(
                text: $text, label: "Start a task with Aria", placeholder: "What would you like to work on?",
                model: "Balanced", effort: "High", onModelPress: {}, onVoice: {}, onSend: { _ in text = "" }
            )
            .nucleuxAddContextMenu(items: [NucleuxContextItem(id: "file", label: "Attach a file")], onSelect: { _ in attach() })
            .nucleuxAttachments(files, onRemove: { id in files.removeAll { $0.id == id } }, onRetry: { id in upload(id) })
        }
        .padding(16)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
    }

    /// The object joins the composer at once; then it uploads (with a real number), is read, and is ready.
    private func attach() {
        let id = "f\(files.count)"
        let fails = files.contains { $0.name == "Northwind-proposal.pdf" }
        files.append(NucleuxAttachment(id: id, name: fails ? "Q3-pricing.xlsx" : "Northwind-proposal.pdf",
                                       kind: fails ? .spreadsheet : .document, state: .uploading,
                                       type: fails ? "Excel" : "PDF · 34 pages", size: fails ? "180 KB" : "2.4 MB", progress: 0))
        upload(id, failAt: fails ? 40 : nil)
    }

    private func upload(_ id: String, failAt: Double? = nil) {
        Task { @MainActor in
            for pct in [18.0, 44, 71, 93, 100] {
                try? await Task.sleep(for: .milliseconds(250))
                guard let i = files.firstIndex(where: { $0.id == id }) else { return }
                if let failAt, pct > failAt { files[i].state = .failed; files[i].progress = nil; return }
                files[i].state = .uploading
                files[i].progress = pct
            }
            guard let i = files.firstIndex(where: { $0.id == id }) else { return }
            files[i].state = .processing
            files[i].progress = nil
            try? await Task.sleep(for: .milliseconds(1100))
            guard let j = files.firstIndex(where: { $0.id == id }) else { return }
            files[j].state = .ready
        }
    }
}

