struct VoiceScreen: View {
    private static let env = ProcessInfo.processInfo.environment
    @State private var text = ProcessInfo.processInfo.environment["COMPOSER_TEXT"] ?? ""
    @State private var sent = ""
    @State private var voice = NucleuxVoiceController(
        granted: env["VOICE_MODE"] == "granted",
        unavailable: env["VOICE_MODE"] == "unavailable"
    )
    private let script = (env["VOICE_SCRIPT"] ?? "summarise open bugs by severity").split(separator: " ").map(String.init)

    var body: some View {
        VStack(spacing: 12) {
            Spacer()
            Text(sent.isEmpty ? " " : "Sent: \(sent)").font(.footnote).accessibilityIdentifier("sent")
            NucleuxPromptComposer(
                text: $text, label: "Start a task with Aria", placeholder: "What would you like to work on?",
                model: "Balanced", effort: "High", onModelPress: {}, onAddContext: {},
                onSend: { sent = $0; text = "" }
            )
            .nucleuxVoice(voice)
        }
        .padding(16)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
        .onChange(of: voice.session.phase) { _, phase in recognize(phase) }
    }

    private func recognize(_ phase: NucleuxVoiceSession.Phase) {
        switch phase {
        case .listening:
            Task { @MainActor in
                for word in script.dropFirst(voice.session.heard.count) {
                    try? await Task.sleep(for: .milliseconds(450))
                    guard voice.session.phase == .listening else { return }
                    voice.level = Double.random(in: 0.55...1)
                    voice.send(.heard(word))
                    try? await Task.sleep(for: .milliseconds(120))
                    voice.level = 0.1
                }
                voice.level = 0
            }
        case .processing:
            Task { @MainActor in
                try? await Task.sleep(for: .seconds(1))
                voice.send(.finish(failed: Self.env["VOICE_MODE"] == "noisy"))
            }
        default:
            break
        }
    }
}

