struct OpenInputScreen: View {
    private static let env = ProcessInfo.processInfo.environment
    @State private var text = env["COMPOSER_TEXT"] ?? ""
    @State private var turns: [(who: String, text: String)] = [
        ("You", "List the launch risks for 2.4."),
        ("Aria", "Three: the payments migration, Legal sign-off, and the Android crash on resume."),
    ]
    @State private var running = false
    @State private var sendError: NucleuxOpenInput.SendError?
    @State private var failNext = env["SEND_FAILS"].flatMap(NucleuxOpenInput.SendError.init(rawValue:))
    @State private var run = 0

    var body: some View {
        VStack(spacing: 8) {
            ScrollView {
                VStack(alignment: .leading, spacing: 14) {
                    ForEach(Array(turns.enumerated()), id: \.offset) { _, t in
                        VStack(alignment: .leading, spacing: 2) {
                            Text(t.who).font(.footnote.weight(.semibold)).foregroundStyle(NucleuxColor.mutedForeground)
                            Text(t.text).foregroundStyle(NucleuxColor.foreground)
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .accessibilityElement(children: .combine)
                    }
                    if running {
                        Text("Aria is comparing with the August release…")
                            .foregroundStyle(NucleuxColor.mutedForeground)
                            .accessibilityIdentifier("working")
                    }
                }
                .padding(.top, 16)
            }
            .defaultScrollAnchor(.bottom)
            NucleuxPromptComposer(
                text: $text, label: "Message Aria", placeholder: "Ask about this project…",
                model: "Balanced", effort: "High", onModelPress: {}, onAddContext: {}, onVoice: {},
                onSend: send
            )
            .nucleuxOpenInput(
                running: running,
                onStop: stop,
                sendError: sendError,
                onRetry: send,
                agentName: "Aria",
                sendKey: Self.env["SEND_KEY"] == "mod" ? .mod : .enter
            )
            .nucleuxComposerStyle(
                appearance: Self.env["APPEARANCE"] == "tonal" ? .tonal : .outlined,
                density: Self.env["DENSITY"] == "compact" ? .compact : .regular
            )
        }
        .padding(.horizontal, 16).padding(.bottom, 8)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
    }

    private func send(_ request: String) {
        if let fail = failNext {
            // Nothing is cleared: the request stays in the field.
            failNext = nil
            sendError = fail
            return
        }
        sendError = nil
        turns.append(("You", request))
        text = "" // only now that it went through
        running = true
        run += 1
        let mine = run
        Task { @MainActor in
            try? await Task.sleep(for: .seconds(Double(Self.env["ANSWER_SECONDS"] ?? "3") ?? 3))
            guard run == mine, running else { return }
            running = false
            turns.append(("Aria", "Two of the three are new since August: payments and the Legal gate."))
        }
    }

    private func stop() {
        run += 1
        running = false
        turns.removeLast() // the withdrawn request; the composer gives it back
    }
}

