import SwiftUI
import Nucleux

struct ProactiveScreen: View {
    private static let env = ProcessInfo.processInfo.environment
    @State private var qa = false
    @State private var owners: [String: String] = [:]
    @State private var clock: Double = 0
    @State private var aria = NucleuxProactiveController(content: NucleuxProactiveContent(
        agent: "Aria",
        reason: "QA is signed off, but two high-priority blockers still have no owner.",
        action: "Assign owners before the release?",
        snoozeLabel: "Remind me tomorrow",
        resolved: "Resolved — both blockers have owners now."
    ))
    private let blockers = [("ONB-112", "Checklist skips the invite step on mobile", "Dana Khoury"),
                            ("EXP-210", "CSV export drops the owner column", "Priya Shah")]
    private var unowned: [String] { blockers.map(\.0).filter { owners[$0] == nil } }

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 14) {
                Text("September release · readiness").font(.headline).foregroundStyle(NucleuxColor.foreground)
                HStack {
                    Text("QA sign-off").foregroundStyle(NucleuxColor.foreground)
                    Spacer()
                    if qa { Text("Done").foregroundStyle(NucleuxColor.mutedForeground) } else {
                        NucleuxButton("Mark QA done", variant: .ghost, size: .sm) { qa = true; observe() }
                    }
                }
                Text("Release blockers").font(.subheadline.weight(.semibold)).foregroundStyle(NucleuxColor.mutedForeground)
                NucleuxProactiveSuggestion(
                    aria,
                    snoozeUntil: { (clock + 24 * 60, "tomorrow, 9:00") },
                    onUndoConfirmed: { owners = [:]; observe() },
                    emphasis: Self.env["EMPHASIS"] == "outlined" ? .outlined : .tonal
                ) {
                    NucleuxProactiveReview(
                        title: "Assign owners", agent: "Aria", confirmLabel: "Assign \(unowned.count) owners",
                        onConfirm: {
                            let n = unowned.count
                            for b in blockers where owners[b.0] == nil { owners[b.0] = b.2 }
                            aria.send(.confirmed(done: "\(n) owners assigned", undo: true))
                        },
                        onCancel: { aria.send(.cancel) }
                    ) {
                        ForEach(blockers.filter { owners[$0.0] == nil }, id: \.0) { b in
                            Text("\(b.0) → \(b.2)").font(.subheadline).foregroundStyle(NucleuxColor.foreground)
                        }
                    }
                }
                ForEach(blockers, id: \.0) { b in
                    HStack {
                        VStack(alignment: .leading) {
                            Text(b.1).foregroundStyle(NucleuxColor.foreground)
                            Text("\(b.0) · High priority").font(.footnote).foregroundStyle(NucleuxColor.mutedForeground)
                        }
                        Spacer()
                        if let o = owners[b.0] { Text(o).font(.footnote).accessibilityIdentifier("owner-\(b.0)") } else {
                            NucleuxButton("Assign \(b.0) to me", variant: .ghost, size: .sm) { owners[b.0] = "You"; observe() }
                        }
                    }
                }
                NucleuxButton("A day passes", variant: .secondary, size: .sm) { clock += 24 * 60; observe() }
            }
            .padding(16)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
    }

    /// Aria speaks up only on evidence: QA done and blockers without an owner.
    private func observe() {
        aria.notice(evidence: qa && !unowned.isEmpty ? unowned.joined(separator: ",") : nil, now: clock)
    }
}

private val content = NucleuxProactiveContent(
    agent = "Aria",
    reason = "QA is signed off, but two high-priority blockers still have no owner.",
    action = "Assign owners before the release?",
    snoozeLabel = "Remind me tomorrow",
    resolved = "Resolved — both blockers have owners now.",
)
private val owners = mutableStateMapOf<String, String>()
private val proposed = mapOf("ONB-112" to "Dana Khoury", "EXP-210" to "Priya Shah")
private val unowned get() = proposed.keys.filter { it !in owners }

private fun setScreen(dark: Boolean = false, emphasis: NucleuxProactiveEmphasis = NucleuxProactiveEmphasis.Tonal) {
    aria = NucleuxProactiveController(content)
    compose.setContent {
        NucleuxTheme(darkTheme = dark) {
            Column(Modifier.fillMaxSize().background(Nucleux.colors.background).padding(16.dp)) {
                NucleuxProactiveSuggestion(
                    aria, snoozeUntil = { 24.0 * 60 to "tomorrow, 9:00" },
                    onUndoConfirmed = { owners.clear() }, emphasis = emphasis,
                ) {
                    NucleuxProactiveReview(
                        "Assign owners", "Aria", "Assign ${unowned.size} owners",
                        onConfirm = {
                            val n = unowned.size
                            owners.putAll(proposed)
                            aria.send(NucleuxProactiveState.Event.Confirmed("$n owners assigned", undo = true))
                        },
                        onCancel = { aria.send(NucleuxProactiveState.Event.Cancel) },
                    ) {
                        unowned.forEach { BasicText("$it → ${proposed[it]}", style = androidx.compose.ui.text.TextStyle(color = Nucleux.colors.foreground)) }
                    }
                }
            }
        }
    }
}

