private val said = mutableListOf<String>()
private var controller: NucleuxNudgeController? = null
private val claims = listOf("Rail, Leeds → London" to "£48.20", "Client lunch" to "£34.00", "Taxi, airport" to "£41.50", "Rail, return" to "£46.80")

private fun setQueue(dark: Boolean = false, approved: Int = 0) {
    compose.setContent {
        CompositionLocalProvider(LocalNucleuxAnnounce provides { said += it }) {
            NucleuxTheme(darkTheme = dark) {
                val c = Nucleux.colors
                val nudges = rememberNucleuxNudgeController(
                    mapOf("check-receipts" to NucleuxNudgeContent("Aria can check these against the receipt first", "", "Let it check them")),
                ).also { controller = it }
                var done by remember { mutableIntStateOf(0) }
                var checked by remember { mutableStateOf(false) }
                fun approve() {
                    done++
                    nudges.nudges["check-receipts"] = nudges.nudges.getValue("check-receipts").copy(detail = "You have approved $done in a row without a change.")
                    if (done >= 3) nudges.earned("check-receipts")
                }
                LaunchedEffect(Unit) { repeat(approved) { approve() } }
                Column(Modifier.fillMaxSize().background(c.background).padding(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
                    BasicText("Expenses · awaiting your approval", style = TextStyle(color = c.foreground, fontSize = 17.sp, fontWeight = FontWeight.SemiBold))
                    BasicText(if (checked) "Queue clear" else "$done approved by you", style = TextStyle(color = c.mutedForeground, fontSize = 13.sp))
                    Spacer(Modifier.weight(1f))
                    if (!checked) {
                        val (title, amount) = claims[done.coerceAtMost(claims.size - 1)]
                        Row(Modifier.fillMaxWidth().border(1.dp, c.border, RoundedCornerShape(12.dp)).padding(14.dp)) {
                            BasicText(title, Modifier.weight(1f), style = TextStyle(color = c.foreground, fontSize = 15.sp, fontWeight = FontWeight.SemiBold))
                            BasicText(amount, style = TextStyle(color = c.foreground, fontSize = 15.sp, fontWeight = FontWeight.SemiBold))
                        }
                    }
                    Spacer(Modifier.weight(1f))
                    NucleuxNudge(nudges, "check-receipts", onAccept = { checked = true }, tailInset = 28.dp)
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        NucleuxButton("Approve", onClick = ::approve, modifier = Modifier.testTag("approve"))
                        NucleuxButton("Query it", onClick = {}, variant = NucleuxButtonVariant.Secondary)
                    }
                }
            }
        }
    }
}

