struct AIMarksScreen: View {
    private static let env = ProcessInfo.processInfo.environment
    static let words = NucleuxAIActionWords(verb: "Rewrite", doing: "Rewriting", status: "Rewriting release note", done: "Release note rewritten.")
    static let draft = "We fixed a bunch of stuff in onboarding and the export thing should work better now."
    @State private var run = NucleuxAIRun()
    @State private var text = AIMarksScreen.env["EMPTY"] == "1" ? "" : AIMarksScreen.draft
    @State private var original = ""
    @State private var job: Task<Void, Never>?

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                HStack(spacing: 8) {
                    NucleuxButton("Preview", variant: .ghost, size: .sm) {}
                    HStack(spacing: 4) {
                        NucleuxButton("Import changelog", variant: .ghost, size: .sm) {}
                        Text("New").font(.system(size: 11, weight: .semibold)).foregroundStyle(NucleuxColor.mutedForeground)
                            .padding(.horizontal, 6).padding(.vertical, 2)
                            .overlay(Capsule().strokeBorder(NucleuxColor.border))
                    }
                    Spacer(minLength: 0)
                    NucleuxAIActionButton(Self.words, working: run.phase == .working,
                                          disabledReason: text.trimmingCharacters(in: .whitespaces).isEmpty ? "Write something first" : nil,
                                          iconOnly: Self.env["ICON_ONLY"] == "1") { start() }
                }
                Text("What changed").font(.system(size: 12, weight: .semibold)).foregroundStyle(NucleuxColor.mutedForeground)
                Text(text.isEmpty ? "Nothing written yet." : text)
                    .font(.system(size: 15)).foregroundStyle(text.isEmpty ? NucleuxColor.mutedForeground : NucleuxColor.foreground)
                    .accessibilityIdentifier("doc")
                // Disclosure: the action explains itself before it runs; the result says what was done and not checked.
                if run.phase == .idle && !text.isEmpty {
                    NucleuxAIActionNote(verb: Self.words.verb, sentence: "Aria rewrites this release note. You review the result before it replaces your text.")
                }
                if run.phase == .done {
                    NucleuxGeneratedResult(details: .init(
                        did: "Rewrote your note to be shorter and clearer. It named the three changes and added nothing that is not in the changelog.",
                        used: "Your draft, the Orbit style guide (14 terms) and the 2.4 changelog.",
                        notChecked: "Whether the changes are shipped: “no longer times out” comes from changelog entry EXP-210.",
                        original: original), agent: "Aria", noun: "release note") { send(.undo); text = original }
                }
                if run.phase == .working { NucleuxAIWorkingStatus(Self.words) { job?.cancel(); send(.stop) } }
                ForEach(Array(run.tools.enumerated()), id: \.offset) { _, t in NucleuxToolUseLine(t) }
            }
            .padding(16)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
    }

    private func send(_ e: NucleuxAIRun.Event) {
        if let said = run.reduce(e, words: Self.words) { AccessibilityNotification.Announcement(said).post() }
    }

    private func start() {
        send(.start)
        job = Task {
            try? await Task.sleep(for: .milliseconds(1500)); guard !Task.isCancelled else { return }
            send(.toolStarted("Checking the style guide…"))
            try? await Task.sleep(for: .milliseconds(1500)); guard !Task.isCancelled else { return }
            send(.toolDone("Style guide checked", detail: "Checked 14 terms against the Orbit style guide: “a bunch of stuff” named as three changes, “the export thing” → “CSV export”."))
            try? await Task.sleep(for: .milliseconds(1000)); guard !Task.isCancelled else { return }
            original = text
            text = "Onboarding is quicker to finish, CSV export no longer times out on large projects, and three small layout fixes are in."
            send(.finish)
        }
    }
}

