import SwiftUI
import Nucleux

struct KnowledgeScreen: View {
    private static let env = ProcessInfo.processInfo.environment
    static func base() -> [NucleuxKnowledgeSource] {
        [("interviews-sept", "Customer interviews — Sept", NucleuxKnowledgeSource.Kind.pdf, NucleuxKnowledgeSource.Origin.upload, "Uploaded 2 days ago"),
         ("interviews-june", "Customer interviews — June", .pdf, .upload, "Uploaded in June"),
         ("analytics", "Onboarding analytics", .sheet, .link, "Linked · follows the original"),
         ("funnel", "Activation funnel — Q3", .sheet, .link, "Linked · follows the original"),
         ("brief", "Product brief v4", .doc, .upload, "Uploaded 3 weeks ago"),
         ("notes", "Usability session notes", .note, .upload, "Uploaded 9 days ago"),
         ("schema", "Schema definitions", .code, .link, "Linked · follows the original"),
         ("spec", "Onboarding spec v2", .drive, .link, "Linked · follows the original")]
            .map { NucleuxKnowledgeSource(id: $0.0, name: $0.1, kind: $0.2, origin: $0.3, fresh: $0.4, state: .ready) }
    }
    static func start() -> [NucleuxKnowledgeSource] {
        var l = base()
        switch env["KB"] {
        case "mixed":
            l[0].state = .failed; l[0].note = "The file is password protected, so it could not be read."
            l[2].state = .unavailable; l[2].note = "The linked file is no longer shared with this project."
            l[3].state = .stale; l[3].fresh = "Linked · the original changed since it was read"
        case "preparing": l = Array(l.prefix(4)).map { var x = $0; x.state = .preparing; return x }
        case "empty": l = []
        default: break
        }
        return l
    }
    @State private var sources = KnowledgeScreen.start()
    @State private var moment: NucleuxKnowledge.Moment? = env["KB"] == "inactive" ? .inactive : env["KB"] == "none" ? .nothingFound : nil
    @State private var activity: String?
    @State private var used: [NucleuxKnowledgeSource] = []
    @State private var text = ""

    var body: some View {
        VStack(spacing: 8) {
            ScrollView {
                VStack(alignment: .leading, spacing: 16) {
                    NucleuxKnowledgeBasePanel(
                        "Product Research", mark: "PR", where: "in this project", sources: sources, moment: moment, activity: activity,
                        noneTopic: "pricing", manage: true, remove: true, switchable: true, deletable: true,
                        onAskWithout: { moment = nil },
                        onAction: { a in
                            switch a {
                            case .activate: moment = nil; say(NucleuxKnowledge.Said.active("Product Research", where: "in this project"))
                            case .deactivate: moment = .inactive; say(NucleuxKnowledge.Said.inactive("Product Research", where: "in this project"))
                            default: break
                            }
                        },
                        onSourceAction: { id, a in
                            guard let i = sources.firstIndex(where: { $0.id == id }) else { return }
                            switch a {
                            case .remove: sources.remove(at: i)
                            case .retry, .reconnect, .refresh:
                                sources[i].state = .ready; sources[i].note = nil
                                if a == .refresh { sources[i].fresh = "Linked · follows the original" }
                                say(a == .reconnect ? NucleuxKnowledge.Said.back(sources[i].name) : NucleuxKnowledge.Said.ready(sources[i].name))
                            case .replace: break
                            }
                        })
                    if !used.isEmpty {
                        NucleuxMessage(agent: "Aria", text: "Onboarding drop-off is mostly at the workspace step: 41% of new teams stop there.")
                        NucleuxKnowledgeProvenance(base: "Product Research", used: used, onOpen: { _ in })
                    }
                }
                .padding(.top, 16)
            }
            if moment != .inactive && !sources.isEmpty {
                HStack {
                    NucleuxKnowledgeChip("Product Research", mark: "PR", sources: sources, moment: moment) {}
                    Spacer()
                    NucleuxButton("Ask about onboarding", variant: .secondary, size: .sm) { ask() }.accessibilityIdentifier("ask")
                }
            }
            NucleuxPromptComposer(text: $text, label: "Message Aria", placeholder: "Ask about this project", onSend: { _ in text = "" })
        }
        .padding(.horizontal, 16).padding(.bottom, 8)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
    }

    private func say(_ s: String) { AccessibilityNotification.Announcement(s).post() }

    private func ask() {
        used = []
        moment = .using
        activity = NucleuxKnowledge.searching("Product Research")
        say(NucleuxKnowledge.Said.searching("Product Research"))
        Task {
            try? await Task.sleep(for: .milliseconds(2500))
            activity = NucleuxKnowledge.reading(4)
            say(NucleuxKnowledge.Said.reading(4))
            try? await Task.sleep(for: .milliseconds(2500))
            used = Array(sources.filter { $0.state == .ready }.prefix(4))
            moment = nil; activity = nil
            say(NucleuxKnowledge.Said.used(used.count, base: "Product Research"))
        }
    }
}

