            .init(name: "create_issue", label: "Create issue", what: "Open an issue on a repository",
                  does: "Opens a new issue with a title, body and labels on a repository you choose.",
                  data: "Writes a new issue. Nothing existing is changed.", risk: .write),
            .init(name: "merge_pull_request", label: "Merge pull request", what: "Merge a pull request into its base branch",
                  does: "Merges the pull request and, where the repository is set up for it, deletes the source branch.",
                  data: "Changes the base branch. This can’t be undone from here.", risk: .destroy),
        ])
    static let fileIt = NucleuxMCPAsk(tool: "create_issue", args: [("project", "WEB"), ("type", "Bug"), ("summary", "Checkout regression"), ("priority", "High")])
    static let failed = NucleuxMCPRun(tool: "update_issue", state: .failed,
                                      why: "WEB-482 could not be updated. Its workflow does not allow that transition from its current status.",
                                      raw: "HTTP 400 · transition_not_allowed")

    private let server = env["MCP"] == "destroy" ? MCPScreen.github : MCPScreen.jira
    @State private var status: NucleuxMCP.Status = Self.startStatus()
    private static func startStatus() -> NucleuxMCP.Status {
        switch env["MCP"] {
        case "validating": .validating
        case "ready", "gate", "toolfail", "destroy": .ready
        case "expired": .expired
        default: .notConnected
        }
    }
    @State private var enabled: [String] = NucleuxMCP.initialEnabled(env["MCP"] == "destroy" ? MCPScreen.github.tools : MCPScreen.jira.tools)
        + (env["MCP"] == "destroy" ? ["merge_pull_request"] : [])
    @State private var always: [String] = []
    @State private var ask: NucleuxMCPAsk? = Self.startAsk()
    private static func startAsk() -> NucleuxMCPAsk? {
        switch env["MCP"] {
        case "gate": MCPScreen.fileIt
        case "destroy": NucleuxMCPAsk(tool: "merge_pull_request", args: [("repository", "signal/web"), ("pull", "#311"), ("method", "squash")])
        default: nil
        }
    }
    @State private var run: NucleuxMCPRun? = env["MCP"] == "toolfail" ? MCPScreen.failed : nil
    @State private var reply = ""
    @State private var text = ""

    var body: some View {
        VStack(spacing: 8) {
            ScrollView {
                VStack(alignment: .leading, spacing: 12) {
                    NucleuxMessage(person: "Priya", text: "File a bug for the checkout regression and set it to high priority.")
                    NucleuxMessage(agent: "Aria", text: "I can write it, but there’s no issue tracker connected. Add one and I’ll file it.")
                    NucleuxMCPPanel(
                        server: server, status: status, enabled: enabled, always: always, ask: ask, run: run, agent: "Aria",
                        technical: Self.env["TECHNICAL"] == "1",
                        onConnect: { _, _ in connect(then: nil) },
                        onCancel: { status = .notConnected },
                        onToggle: { t, on in enabled = on ? enabled + [t] : enabled.filter { $0 != t } },
                        onDecide: { d in
                            guard let a = ask else { return }
                            ask = nil
                            if d == .deny { reply = "Left it alone. Nothing was sent to \(server.name)."; return }
                            if d == .always { always.append(a.tool) }
                            run = NucleuxMCPRun(tool: a.tool, state: .running)
                            Task {
                                try? await Task.sleep(for: .milliseconds(1000))
                                run = NucleuxMCPRun(tool: a.tool, state: .done, detail: "WEB-482")
                                reply = "Filed as WEB-482 in WEB, priority High."
                            }
                        },
                        onRetry: {
                            run = NucleuxMCPRun(tool: "update_issue", state: .running)
                            Task {
                                try? await Task.sleep(for: .milliseconds(800))
                                run = nil
                                status = .expired
                            }
                        },
                        onReconnect: { connect(then: NucleuxMCPRun(tool: "update_issue", state: .done, detail: "WEB-482")) },
                        onDisconnect: { status = .disconnected; run = nil; ask = nil })
                    if !reply.isEmpty { NucleuxMessage(agent: "Aria", text: reply) }
                }
                .padding(.top, 16)
            }
            if status == .ready {
                HStack {
                    NucleuxMCPChip(server.name, mark: server.mark, enabled: enabled.count, status: status) {}
                    Spacer()
                    if ask == nil && run == nil {
                        NucleuxButton("Let it file the bug", variant: .secondary, size: .sm) { ask = Self.fileIt }.accessibilityIdentifier("use")
                    } else if run?.state == .done && run?.tool == "create_issue" {
                        NucleuxButton("Now let a call fail", variant: .secondary, size: .sm) { breakOne() }.accessibilityIdentifier("break")
                    }
                }
            }
            NucleuxPromptComposer(text: $text, label: "Message Aria", placeholder: "Ask Aria", onSend: { _ in text = "" })
        }
        .padding(.horizontal, 16).padding(.bottom, 8)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
    }

    private func connect(then: NucleuxMCPRun?) {
        status = .reaching
        Task {
            try? await Task.sleep(for: .milliseconds(900))
            status = .validating
            try? await Task.sleep(for: .milliseconds(900))
            status = .discovering
            try? await Task.sleep(for: .milliseconds(900))
            status = .ready
            if let then { run = then; reply = "Signed back in and the update went through." }
        }
    }

    private func breakOne() {
        reply = ""
        run = NucleuxMCPRun(tool: "update_issue", state: .running)
        Task {
            try? await Task.sleep(for: .milliseconds(900))
            run = Self.failed
        }
    }
}

private val M = NucleuxMcp
private val jira = server("jira")
private val said = mutableListOf<String>()
private var status by mutableStateOf(NucleuxMcp.Status.NotConnected)
private var enabled by mutableStateOf(emptyList<String>())
private var always by mutableStateOf(emptyList<String>())
private var ask by mutableStateOf<NucleuxMcpAsk?>(null)
private var run by mutableStateOf<NucleuxMcpRun?>(null)
private val calls = mutableListOf<String>()

private fun setPanel(srv: NucleuxMcpServer = jira, start: NucleuxMcp.Status = NucleuxMcp.Status.NotConnected, technical: Boolean = false, dark: Boolean = false) {
    status = start
    enabled = M.initialEnabled(srv.tools)
    compose.setContent {
        CompositionLocalProvider(LocalNucleuxAnnounce provides { said += it }) {
            NucleuxTheme(darkTheme = dark) {
                Column(Modifier.fillMaxSize().background(Nucleux.colors.background).verticalScroll(rememberScrollState()).padding(16.dp)) {
                    NucleuxMcpPanel(
                        srv, status, enabled,
                        onConnect = { n, u -> calls += "connect:$n:$u"; status = NucleuxMcp.Status.Reaching },
                        always = always, ask = ask, run = run, agent = "Aria", technical = technical,
                        onToggle = { t, on -> enabled = if (on) enabled + t else enabled - t },
                        onDecide = { d ->
                            calls += d.key
                            val a = ask!!
                            if (d == NucleuxMcp.Decision.Always) always = always + a.tool
                            run = if (d == NucleuxMcp.Decision.Deny) null else NucleuxMcpRun(a.tool, NucleuxMcp.RunState.Running)
                            ask = null
                        },
                        onRetry = { status = NucleuxMcp.Status.Expired },
                        onReconnect = { status = NucleuxMcp.Status.Reaching },
                        onDisconnect = { status = NucleuxMcp.Status.Disconnected },
                    )
                }
            }
        }
    }
}

import 'package:flutter/material.dart';
