final jira = server('jira');

Future<void> panel(
  WidgetTester tester, {
  NucleuxMcpServer? srv,
  NucleuxMcpStatus start = NucleuxMcpStatus.notConnected,
  NucleuxMcpAsk? startAsk,
  NucleuxMcpRun? startRun,
  bool technical = false,
}) async {
  tester.view.physicalSize = const Size(402, 1800);
  tester.view.devicePixelRatio = 1;
  addTearDown(tester.view.reset);
  said = [];
  calls = [];
  final s = srv ?? jira;
  st = start;
  enabled = M.initialEnabled(s.tools);
  always = [];
  ask = startAsk;
  run = startRun;
  await tester.pumpWidget(
    MaterialApp(
      home: Scaffold(
        body: SingleChildScrollView(
          padding: const EdgeInsets.all(16),
          child: StatefulBuilder(
            builder: (context, set) {
              rebuild = set;
              return NucleuxMcpPanel(
                server: s,
                status: st,
                enabled: enabled,
                always: always,
                ask: ask,
                run: run,
                agent: 'Aria',
                technical: technical,
                onConnect: (n, u) => set(() {
                  calls.add('connect:$n:$u');
                  st = NucleuxMcpStatus.reaching;
                }),
                onToggle: (t, on) => set(
                  () => enabled = on
                      ? [...enabled, t]
                      : [
                          for (final x in enabled)
                            if (x != t) x,
                        ],
                ),
                onDecide: (d) => set(() {
                  calls.add(d.name);
                  final a = ask!;
                  if (d == NucleuxMcpDecision.always) {
                    always = [...always, a.tool];
                  }
                  run = d == NucleuxMcpDecision.deny
                      ? null
                      : NucleuxMcpRun(
                          tool: a.tool,
                          state: NucleuxMcpRunState.running,
                        );
                  ask = null;
                }),
                onRetry: () => set(() => st = NucleuxMcpStatus.expired),
                onReconnect: () =>
                    set(() => st = NucleuxMcpStatus.reaching),
                onDisconnect: () =>
                    set(() => st = NucleuxMcpStatus.disconnected),
              );
            },
          ),
        ),
      ),
    ),
  );
}

