struct ConnectScreen: View {
    private static let env = ProcessInfo.processInfo.environment
    static func svc(_ id: String, _ name: String, _ mark: String, _ purpose: String, _ account: String, _ what: String,
                    _ benefits: [NucleuxConnectService.Benefit], _ canSee: [String]) -> NucleuxConnectService {
        NucleuxConnectService(id: id, name: name, mark: mark, purpose: purpose,
                              blurb: "Use the \(what) you already have access to when answering relevant questions.", account: account,
