                              canSee: canSee, useLine: "The agent can use \(what) you can access.")
    }
    static let drive = NucleuxConnectService(
        id: "googledrive", name: "Google Drive", mark: "GD", purpose: "Files and documents",
        blurb: "Use the files and folders you already have access to when answering relevant questions.", account: "j.rivera@northwind.example",
