                   .init(icon: .doc, title: "Read file contents", what: "documents, sheets and slides you have access to"),
                   .init(icon: .shield, title: "You stay in control", what: "Disconnect Google Drive whenever you want.")],
        canSee: ["Files and folders you can access", "Document contents", "Relevant shared drives"],
        useLine: "The agent can use files and folders you can access, including their contents.")
    static let others = [
        svc("slack", "Slack", "SL", "Messages and channels", "Northwind · @jordan", "messages in the channels",
            [.init(icon: .search, title: "Search channels you’re in", what: "public and private channels you already belong to"),
             .init(icon: .chat, title: "Read messages and threads", what: "text you can already see in those channels")],
            ["Channels you belong to", "Messages and threads"]),
        svc("github", "GitHub", "GH", "Issues and pull requests", "jordan-work", "issues and pull requests",
            [.init(icon: .search, title: "Search repositories", what: "the repositories your GitHub account can already access"),
             .init(icon: .code, title: "Read issues and pull requests", what: "titles, status, labels, comments and history")],
            ["Repositories you can access", "Issues and pull requests"]),
        svc("notion", "Notion", "NO", "Docs and wikis", "Northwind workspace", "pages and databases",
            [.init(icon: .search, title: "Search shared pages", what: "pages and databases shared with your account")],
            ["Pages and databases you can access"]),
    ]
    static let wall = "The research you’re asking about is in files I’ve never been given. Connecting Google Drive lets me read the ones you can already open."

    @State private var state: NucleuxConnect.State = Self.startState()
    private static func startState() -> NucleuxConnect.State {
        switch env["CONN"] {
        case "authorise": .authorise
        case "connecting": .connecting
        case "connected", "sources", "manage": .connected
        case "active": .active
        case "stale": .stale
        case "error": .error
        case "blocked": .blocked
        default: .available
        }
    }
    @State private var phase: NucleuxConnect.Phase = .reading
    @State private var answered = false
    @State private var sheet: String? = Self.startSheet()
    private static func startSheet() -> String? {
        switch env["CONN"] {
        case "sources": "sources"
        case "manage": "manage"
        default: nil
        }
    }
    @State private var slackOn = false
    @State private var text = ""

    private var items: [NucleuxConnect.Item] {
        [NucleuxConnect.Item(service: Self.drive, connected: state != .available && state != .authorise && state != .connecting && state != .error && state != .blocked,
                             state: state == .stale ? .stale : nil),
         NucleuxConnect.Item(service: Self.others[0], connected: true, enabled: slackOn),
         NucleuxConnect.Item(service: Self.others[1], connected: false, state: .error),
         NucleuxConnect.Item(service: Self.others[2], connected: false, state: .blocked)]
    }

    var body: some View {
        VStack(spacing: 8) {
            ScrollView {
                VStack(alignment: .leading, spacing: 12) {
                    NucleuxMessage(person: "Jordan", text: "Summarise the main onboarding problems from our latest customer research.")
                    NucleuxMessage(agent: "Aria") {
                        NucleuxConnectCard(Self.drive, state: state, inline: true, wall: Self.wall,
                                           activity: state == .active ? (phase, phase == .searching ? 0 : 5) : nil) { act($0) }
                    }
                    if answered {
                        NucleuxMessage(agent: "Aria", text: "Three problems come up in most sessions: the workspace step, invite emails landing in spam, and an unclear first project.")
                    }
                }
                .padding(.top, 16)
            }
            HStack {
                if NucleuxConnect.states[state]!.live && state != .limited {
                    NucleuxConnectChip(Self.drive, state: .connected) { sheet = "manage" }
                }
                Spacer()
                NucleuxButton("Sources", variant: .ghost, size: .sm) { sheet = "sources" }.accessibilityIdentifier("open-sources")
            }
            NucleuxPromptComposer(text: $text, label: "Message Aria", placeholder: "Ask Aria", onSend: { _ in text = "" })
        }
        .padding(.horizontal, 16).padding(.bottom, 8)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
        .sheet(isPresented: Binding(get: { sheet != nil }, set: { if !$0 { sheet = nil } })) {
            ScrollView {
                Group {
                    if sheet == "manage" {
                        NucleuxConnectManage(Self.drive, state: state == .stale ? .stale : .connected, onReconnect: { state = .connected; sheet = nil },
                                             onDisconnect: { state = .available; sheet = nil }, onDone: { sheet = nil })
                    } else {
                        VStack(alignment: .leading, spacing: 12) {
                            Text("Your data sources").font(.system(size: 17, weight: .semibold)).foregroundStyle(NucleuxColor.foreground)
                            NucleuxConnectSources(items, headings: true, onAction: { id, _ in if id == "googledrive" { sheet = nil; state = .authorise } },
                                                  onToggle: { id, on in if id == "slack" { slackOn = on } }, onOpen: { _ in sheet = "manage" })
                        }
                    }
                }
                .padding(20)
            }
            .background(NucleuxColor.background)
            .presentationDetents([.medium, .large])
        }
    }

    private func act(_ a: NucleuxConnect.Action) {
        switch a {
        case .connect: state = .authorise
        case .allow, .retry:
            state = .connecting
            Task {
                try? await Task.sleep(for: .milliseconds(1500))
                guard state == .connecting else { return }
                state = .active
                phase = .searching
                try? await Task.sleep(for: .milliseconds(1000))
                phase = .reading
                try? await Task.sleep(for: .milliseconds(1000))
                phase = .done
                answered = true
                try? await Task.sleep(for: .milliseconds(600))
                state = .connected
            }
        case .cancel: state = .available
        case .reconnect: state = .connecting; Task { try? await Task.sleep(for: .milliseconds(1200)); state = .connected }
        case .manage: sheet = "manage"
        case .ask: break
        }
    }
}

