                    ForEach(Array(turns.enumerated()), id: \.offset) { _, t in
                        Text(t.0).font(.system(size: 15)).foregroundStyle(NucleuxColor.foreground)
                        Text(NucleuxStyles.agentLine("Aria", style.styles, t.1)).font(.system(size: 12, weight: .semibold)).foregroundStyle(NucleuxColor.mutedForeground)
                            .accessibilityIdentifier("agent-line")
                    }
                    if let creator {
                        NucleuxStyleCreator(control: creator, preview: NucleuxStylePreviews(question: "Summarize the October release.",
                            answers: ["house": "New: shared dashboards — your whole team sees the same numbers. Faster: exports take half the time."]))
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.top, 16)
            }
