            NucleuxPromptComposer(text: $text, label: "Message Aria", placeholder: "Describe the task…", onSend: { t in
                turns.append((t, style.style))
                mode.sent(); tone.sent(); style.sent()
                text = ""
            })
            .nucleuxComposerSettings([mode.setting(agent: "Aria"), tone.setting(), style.setting()])
        }
        .padding(.horizontal, 16).padding(.bottom, 8)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
