                let c = NucleuxStyleCreateControl(
                    taken: { style.styles.map(\.id) },
                    // The demo's stand-in for the host's AI step.
                    generate: { _, _ in try? await Task.sleep(for: .seconds(1)); return Self.house },
                    onSave: { saved, use in style.add(saved, use: use); creator = nil })
                c.open()
                creator = c
            }
