private val said = mutableListOf<String>()
private val sent = mutableListOf<Pair<String, String>>()
private val reply = CompletableDeferred<NucleuxStyleDraft?>()

private fun conversation(start: String = NucleuxStyles.NORMAL, dark: Boolean = false) {
    compose.setContent {
        CompositionLocalProvider(LocalNucleuxAnnounce provides { said += it }) {
            NucleuxTheme(darkTheme = dark) {
                Column(Modifier.fillMaxSize().background(Nucleux.colors.background).padding(16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    var text by remember { mutableStateOf("Now draft the customer email about it.") }
                    val style = rememberStyleControl(style = start)
                    style.replies = true
                    val creator = rememberStyleCreateControl(taken = { style.styles.map { it.id } }, generate = { _, _ -> reply.await() },
                        onSave = { saved, use -> style.add(saved, use) })
                    style.onCreate = { creator.open() }
                    NucleuxStyleCreator(creator, preview = "Summarize the October release." to "New: shared dashboards — your whole team sees the same numbers.")
                    Spacer(Modifier.weight(1f))
                    NucleuxPromptComposer(
                        text = text, onTextChange = { text = it }, label = "Message Aria",
                        onSend = { sent += it to style.style; style.sent() },
                        settings = listOf(style.setting()),
                    )
                }
            }
        }
    }
}

