import SwiftUI
import Nucleux

struct MadlibsScreen: View {
    static let madlib = NucleuxMadlib(
        id: "stakeholder-summary", sentence: "Create a summary of {project} for {audience}[, focusing on {topic}].",
        blanks: [
            .init(id: "project", label: "Project", required: true, suggestions: ["Checkout redesign", "Mobile onboarding", "Pricing v2"]),
            .init(id: "audience", label: "Audience", required: true, suggestions: ["leadership", "sales", "customer success"]),
            .init(id: "topic", label: "Topic", required: false, suggestions: ["risks", "the timeline", "customer impact"]),
        ])
    @State private var text = ""
    @State private var placed: String?
    @State private var sent: [String] = []
    @State private var control: NucleuxMadlibControl?

    var body: some View {
        VStack(spacing: 8) {
            ScrollView {
                VStack(alignment: .leading, spacing: 12) {
                    Text("I need a summary for stakeholders.").font(.system(size: 15)).foregroundStyle(NucleuxColor.foreground)
                    Text("Tell me which project, who it’s for and what to focus on:").font(.system(size: 15)).foregroundStyle(NucleuxColor.mutedForeground)
                    if let control { NucleuxMadlibCard(control: control, useLabel: NucleuxMadlibs.useLabel(composerText: text, placed: placed)) }
                    ForEach(Array(sent.enumerated()), id: \.offset) { _, t in
                        Text(t).font(.system(size: 15)).foregroundStyle(NucleuxColor.foreground).accessibilityIdentifier("sent")
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding(.top, 16)
            }
            NucleuxPromptComposer(text: $text, label: "Message Aria", placeholder: "Or write your own request…", onSend: { t in
                sent.append(t)
                text = ""
            })
        }
        .padding(.horizontal, 16).padding(.bottom, 8)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(NucleuxColor.background)
        .onAppear {
            guard control == nil else { return }
            let c = NucleuxMadlibControl(Self.madlib) { t in text = t; placed = t }
            // The demo's stand-in for a value the host can infer from the page.
            if ProcessInfo.processInfo.environment["INFER"] == "1" { c.send(.suggest("project", "Checkout redesign")) }
            control = c
        }
    }
}

private val M = NucleuxMadlibs
private val summary by lazy { madlib(f.getJSONObject("madlib")) }
private val said = mutableListOf<String>()
private var text by mutableStateOf("")

private fun card(suggest: Boolean = false, dark: Boolean = false): NucleuxMadlibControl {
    lateinit var control: NucleuxMadlibControl
    compose.setContent {
        CompositionLocalProvider(LocalNucleuxAnnounce provides { said += it }) {
            NucleuxTheme(darkTheme = dark) {
                Column(Modifier.fillMaxSize().background(Nucleux.colors.background).padding(16.dp).verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    control = rememberMadlibControl(summary) { text = it }
                    NucleuxMadlibCard(control, useLabel = M.useLabel(text, null))
                }
            }
        }
    }
    if (suggest) { compose.runOnIdle { control.send(NucleuxMadlibs.Event.Suggest("project", "Checkout redesign")) }; compose.waitForIdle() }
    return control
}

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nucleux/nucleux.dart';

final summary = madlib(f['madlib']);

Future<(NucleuxMadlibControl, List<String>)> card(WidgetTester tester) async {
  tester.view.physicalSize = const Size(1206, 2622);
  tester.view.devicePixelRatio = 3;
  addTearDown(tester.view.reset);
  final placed = <String>[];
  final control = NucleuxMadlibControl(summary, onPlace: placed.add);
  addTearDown(control.dispose);
  await tester.pumpWidget(
    MaterialApp(
      home: Scaffold(
        body: SingleChildScrollView(
          padding: const EdgeInsets.all(16),
          child: NucleuxMadlibCard(control: control),
        ),
      ),
    ),
  );
  return (control, placed);
}

